$ErrorActionPreference = 'Stop'
$RunId = 'powershell_operation_scale_200_tshark'
$Client = 'powershell'
$LocalDir = 'data\eval\generated\workloads\powershell\local\powershell_operation_scale_200_tshark'
$GroundTruthPath = Join-Path $PSScriptRoot '..\..\ground_truth\powershell_operation_scale_200_tshark.jsonl'
New-Item -ItemType Directory -Path (Split-Path $GroundTruthPath) -Force | Out-Null
New-Item -ItemType Directory -Path $LocalDir -Force | Out-Null
Remove-Item -Path $GroundTruthPath -Force -ErrorAction SilentlyContinue

function New-ScfLocalFile {
    param([string]$Path, [int]$Size)
    New-Item -ItemType Directory -Path (Split-Path $Path) -Force | Out-Null
    $bytes = New-Object byte[] $Size
    for ($i = 0; $i -lt $Size; $i++) { $bytes[$i] = 65 + ($i % 26) }
    [IO.File]::WriteAllBytes($Path, $bytes)
}

function Invoke-ScfOp {
    param(
        [int]$OpId,
        [string]$Event,
        [string]$PathValue,
        [AllowNull()][string]$TargetPath,
        [string]$Variant,
        [string]$CommandText,
        [scriptblock]$Body
    )
    $start = (Get-Date).ToUniversalTime().ToString('o')
    $exitCode = 0
    $errorText = $null
    try {
        & $Body
    } catch {
        $exitCode = 1
        $errorText = $_.Exception.Message
    }
    $record = [ordered]@{
        run_id = $RunId
        op_id = $OpId
        client = $Client
        event = $Event
        path = $PathValue
        target_path = $TargetPath
        status = $(if ($exitCode -eq 0) { 'success' } else { 'failed' })
        start_time = $start
        end_time = (Get-Date).ToUniversalTime().ToString('o')
        command = $CommandText
        exit_code = $exitCode
        operation_variant = $Variant
        error = $errorText
    }
    $record | ConvertTo-Json -Compress | Add-Content -Encoding UTF8 -Path $GroundTruthPath
    if ($exitCode -ne 0) { throw "SCF operation $OpId failed: $errorText" }
}

